import {merEvidence} from './mer-evidence.js';
import {viking2Reading} from './viking2-details.js';
import {componentReading as ds2Reading} from './ds2-details.js?v=20261023b';
const explanations={
solar:['De la luz a la electricidad','Las células convierten parte de la luz solar en energía eléctrica. Los contactos de cada célula se conectan entre sí para llevar esa energía a los sistemas del vehículo. En esta vista las capas están separadas para distinguir el vidrio protector, la célula y su soporte.','La generación depende de la iluminación disponible. El polvo y las sombras pueden reducirla; por eso un panel es también una pieza clave para comprender el final de varias misiones marcianas.'],
wheels:['Moverse sobre otro mundo','El motor transforma energía eléctrica en movimiento y la transmisión lleva ese movimiento a la rueda. Los apoyos y las articulaciones sostienen el vehículo y permiten que sus ruedas se adapten a las irregularidades del terreno.','Selecciona la transmisión o el motor para ver cómo se relacionan con la rueda. El corte deja visibles piezas que normalmente estarían protegidas dentro del conjunto.'],
avionics:['El centro de control del vehículo','La electrónica recibe instrucciones, procesa lecturas de los instrumentos y coordina las operaciones. Las placas reúnen componentes conectados por pistas conductoras, mientras que los arneses llevan señales y alimentación a otros sistemas.','Puedes seguir el recorrido desde las placas hasta un circuito integrado y sus contactos. El modelo muestra esas relaciones funcionales, sin reproducir un esquema electrónico de fabricación.'],
pancam:['Observar las rocas a distancia','Pancam era el sistema de cámaras panorámicas de Spirit y Opportunity. Sus dos puntos de vista permitían estudiar la forma del terreno; las observaciones con filtros ayudaban a comparar el aspecto de las rocas en distintas bandas.','El corte permite inspeccionar las lentes, el detector y la rueda de filtros. El mástil elevaba las cámaras por encima del cuerpo del rover para observar su entorno.'],
seis:['Escuchar el movimiento de Marte','SEIS registraba las vibraciones del suelo. El instrumento se colocó sobre la superficie, separado del cuerpo del lander, para observar señales que ayudan a investigar el interior del planeta.','La protección contra el viento y los cambios de temperatura limitaba perturbaciones. En el corte puedes explorar esa protección, los sensores y el sistema de apoyo.'],
tega:['Buscar pistas en los gases','El analizador TEGA de Phoenix recibía pequeñas muestras del suelo y las calentaba. El estudio de los gases liberados permitía investigar los materiales y compuestos volátiles presentes en esas muestras.','La vista abierta distingue los hornos y los conductos del conjunto. La separación de las piezas es una ayuda visual para seguir la función de cada etapa del análisis.'],
rtg:['Electricidad a partir de calor','Los landers Viking obtenían electricidad de generadores termoeléctricos de radioisótopos. Estos aprovechaban el calor de una fuente radiactiva mediante elementos termoeléctricos; su funcionamiento no dependía de recibir luz solar.','El corte permite distinguir la fuente de calor, los elementos de conversión y las superficies que liberan calor hacia el exterior.'],
biology:['Un laboratorio sobre Marte','Viking llevaba experimentos para investigar muestras de suelo marciano. El brazo entregaba material al sistema de análisis, que estudiaba sus respuestas bajo distintas condiciones.','Los resultados no confirmaron la existencia de vida. Aquí puedes explorar las cámaras y las conexiones del laboratorio como un conjunto funcional.'],
ascent:['La cabina que volvió a despegar','La etapa de ascenso del módulo lunar alojaba a los dos astronautas durante las operaciones en la superficie y el regreso a la órbita lunar. Sus instrumentos permitían supervisar el vehículo y controlar sus maniobras.','Esta parte no quedó junto a la etapa de descenso: despegó de la Luna. La cabina del visor representa el vehículo histórico y sus puestos de control de forma educativa.'],
descent:['Controlar el descenso hasta la Luna','La etapa inferior reunía la propulsión de descenso, los depósitos y el tren de aterrizaje. El motor permitió regular la maniobra final, mientras que las patas transmitían las cargas hacia los platos de apoyo.','Tras el despegue de los astronautas, esta etapa permaneció en la superficie. Explora los depósitos, las líneas de alimentación y el motor en el corte.'],
antenna:['El vínculo con la misión','Una antena transmite o recibe señales electromagnéticas. En los sistemas con reflector, su forma concentra la señal hacia una dirección; los equipos de radio convierten la información en una señal que puede viajar entre la nave y sus enlaces de comunicación.','Puedes pasar del reflector al alimentador y a la electrónica del enlace. La orientación, la energía disponible y el funcionamiento de la radio son esenciales para mantener las comunicaciones.'],
arm:['Acercar la ciencia al terreno','Un brazo robótico combina articulaciones, actuadores y una herramienta terminal. Esa cadena de mecanismos permite situar un instrumento, manipular una muestra o trabajar sobre una roca sin desplazar todo el vehículo.','Sigue las etiquetas para explorar la articulación, el cableado y la herramienta propia de esta misión.'],
sampler:['Del suelo al instrumento','El mecanismo de muestreo recogía material de la superficie para estudiarlo. Sus articulaciones posicionaban la herramienta y el sistema de control coordinaba los movimientos.','La vista abierta ayuda a seguir cómo una orden eléctrica se convierte en una acción mecánica sobre el terreno.'],
seats:['Conducir sobre la Luna','El rover lunar tenía dos puestos abiertos para los astronautas, un mando de conducción y equipos de navegación y comunicaciones. Sus baterías suministraban energía al vehículo.','Este conjunto permite inspeccionar el mando, la instrumentación y la alimentación, sin ocultarlos bajo las cubiertas exteriores.'],
forebody:['Investigar bajo la superficie','El cuerpo delantero de Deep Space 2 estaba diseñado para penetrar el suelo marciano. Un pequeño sistema de muestreo y análisis debía investigar el material alcanzado bajo la superficie.','No se recibió una señal de las microsondas. Esta vista explica el diseño previsto; no muestra un estado de despliegue confirmado.'],
aftbody:['Transmitir desde la superficie','El cuerpo posterior de Deep Space 2 debía quedar sobre el terreno y comunicar la información de la sonda mediante un orbitador. Un cable flexible lo conectaba con el cuerpo penetrador.','La falta de comunicación impide confirmar qué ocurrió tras la llegada. El conjunto abierto muestra la función prevista de la microelectrónica.']
};
export function componentReading(part,mission){
 if(mission.id==='ds2')return ds2Reading(part,mission);
 if(mission.id==='surveyor')return surveyorEvidence(part,mission);
 if(mission.family==='mer'&&mission.fleet?.mechanisms)return merEvidence(part,mission);
 if(mission.id==='viking2')return viking2Reading(part,mission);
 if(mission.family==='viking')return vikingEvidence(part,mission);
 if(mission.id==='phoenix')return phoenixEvidence(part,mission);
 if(!part)return '';
 if(mission.id==='insight')return insightEvidence(part);
 if(['eagle','lrv15','sojourner'].includes(mission.id)&&part.evidence)return archiveEvidence(part,mission);
 const e=explanations[part.id];
 if(e)return `<h3>${e[0]}</h3><p>${e[1]}</p><p>${e[2]}</p>`;
 return '';
}

const text=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function archiveEvidence(part, mission) {
 const labels = {
  DOCUMENTED: 'Documentado',
  VISUALLY_RECONSTRUCTED: 'Reconstrucción visual',
  INFERRED: 'Representación educativa'
 };
 const geometry = part.geometryFidelity || part.evidence;
 const references = (part.evidenceRefs || []).map(key => mission.fleet?.references?.[key]).filter(ref => ref?.url);
 const links = references.map(ref =>
  `<li><a href="${text(ref.url)}" target="_blank" rel="noopener noreferrer">${text(ref.title || ref.label || ref.url)} →</a></li>`
 ).join('');
 return `<p class="insight-certainty">${text(labels[geometry] || geometry)}</p>` +
  (part.detailLimit ? `<p class="insight-scope">${text(part.detailLimit)}</p>` : '') +
  (links ? `<details class="insight-evidence"><summary>Fuentes de este componente</summary><ul>${links}</ul></details>` : '');
}
function phoenixEvidence(part,mission){
 const refs=mission.fleet?.references||{},keys=part?.evidenceRefs||['telecom','kit','hardware','deck','integration'],certainty=part?.evidence||'VISUALLY_RECONSTRUCTED';
 const labels={DOCUMENTED:'DOCUMENTADO · arquitectura y función',VISUALLY_RECONSTRUCTED:'RECONSTRUCCIÓN BASADA EN DOCUMENTACIÓN',INFERRED:'REPRESENTACIÓN EDUCATIVA'};
 const scope=part?certainty==='INFERRED'?'Las pistas de PCB, el bobinado, los conectores y las rutas finas explican principios conocidos; no reproducen planos de fabricación de Phoenix.':'La documentación confirma el instrumento, su función y las cantidades indicadas. La geometría fina se ajusta a fotografías; no es un CAD de vuelo. La elevación de piezas sirve para inspeccionarlas, no representa un despliegue histórico.':'Phoenix tiene una reconstrucción propia de su plataforma e instrumentos. El brazo extendido sigue la arquitectura de aluminio y titanio documentada por JPL; su pose es representativa y la biobarrera de transporte está retirada. El contorno y las posiciones de los contactos solares se basan en PIA09701. El acabado de las células es un material PBR propio. Los detalles sin cotas públicas y el interior electrónico se identifican como aproximaciones educativas.';
 return `<p class="insight-certainty">${labels[certainty]||labels.INFERRED}</p><p class="insight-scope">${scope}</p><details class="insight-evidence surveyor-evidence"><summary>${part?'Fuentes de este componente':'Documentación de Phoenix'}</summary>${keys.map(key=>{const r=refs[key];if(!r)return '';return `<div class="surveyor-reference">${r.image?`<figure><a href="${text(r.image)}" target="_blank" rel="noopener" aria-label="Ampliar ${text(r.title)}"><img src="${text(r.image)}" alt="${text(r.caption)}" loading="lazy"></a><figcaption>${text(r.caption)} ${text(r.mediaNote||'Fotografía histórica NASA/JPL; conversión a WebP sin cambiar su contenido.')}</figcaption></figure>`:''}<a href="${text(r.url)}" target="_blank" rel="noopener">${text(r.title)} ↗</a></div>`;}).join('')}</details>`;
}
function vikingEvidence(part,mission){
 const refs=mission.fleet?.references||{},keys=part?.evidenceRefs||['configuration','overview'],certainty=part?.evidence||'VISUALLY_RECONSTRUCTED';
 const labels={DOCUMENTED:'DOCUMENTADO · arquitectura y función',VISUALLY_RECONSTRUCTED:'RECONSTRUCCIÓN BASADA EN DOCUMENTACIÓN',INFERRED:'REPRESENTACIÓN EDUCATIVA'};
 const scope=part?certainty==='INFERRED'?'El corte explica un subsistema histórico. Las pistas de PCB, el bobinado, el cableado fino y las dimensiones internas no reproducen planos de fabricación confirmados.':'NASA confirma el equipo y su función. La envolvente y su distribución se reconstruyen de los esquemas; los detalles sin cotas públicas son aproximados.':'Lander en superficie: depósitos y tres motores en el exterior del cuerpo. El espejo de aumento es un instrumento de ciencia; no forma parte de la antena. Las líneas de refrigeración y llenado quedan desconectadas tras el descenso.';
 return `<p class="insight-certainty">${labels[certainty]||labels.INFERRED}</p><p class="insight-scope">${scope}</p><details class="insight-evidence surveyor-evidence"><summary>${part?'Evidencia de este componente':'Planos utilizados para Viking'}</summary>${keys.map(key=>{const r=refs[key];if(!r)return '';return `<div class="surveyor-reference">${r.image?`<figure><a href="${text(r.image)}" target="_blank" rel="noopener" aria-label="Ampliar ${text(r.title)}"><img src="${text(r.image)}" alt="${text(r.caption)}" loading="lazy"></a><figcaption>${text(r.caption)} Fuente: NASA. Recorte y rotación para facilitar la lectura; el dibujo histórico no se modifica.</figcaption></figure>`:''}<a href="${text(r.url)}" target="_blank" rel="noopener">${text(r.title)} ↗</a></div>`;}).join('')}</details>`;
}
function surveyorEvidence(part,mission){
 const refs=mission.fleet?.references||{},keys=part?.evidenceRefs||Object.keys(refs),certainty=part?.evidence||'VISUALLY_RECONSTRUCTED';
 const labels={DOCUMENTED:'DOCUMENTADO · arquitectura y función',VISUALLY_RECONSTRUCTED:'RECONSTRUCCIÓN BASADA EN DOCUMENTACIÓN',INFERRED:'REPRESENTACIÓN EDUCATIVA'};
 const scope=part?certainty==='INFERRED'?'El corte y los detalles internos explican funciones conocidas. No son un plano ni un circuito de fabricación de Surveyor III.':'La fuente confirma el equipo y su arquitectura. La forma y las dimensiones pequeñas se reconstruyen visualmente; no equivalen a un CAD de vuelo.':'Configuración de superficie anterior a la recuperación por Apollo 12. El retrocohete central ya se había desprendido; puedes estudiarlo en la vista de propulsión de vuelo.';
 return `<p class="insight-certainty">${labels[certainty]||labels.VISUALLY_RECONSTRUCTED}</p><p class="insight-scope">${scope}</p><details class="insight-evidence surveyor-evidence"><summary>${part?'Evidencia de este componente':'Fuentes de la reconstrucción de Surveyor III'}</summary>${keys.map(key=>{const r=refs[key];if(!r)return '';return `<div class="surveyor-reference">${r.image?`<figure><a href="${text(r.image)}" target="_blank" rel="noopener" aria-label="Ampliar ${text(r.title)}"><img src="${text(r.image)}" alt="${text(r.caption)}" loading="lazy"></a><figcaption>${text(r.caption)} Fuente: NASA/JPL; figura del documento histórico. Conversión a WebP sin alterar el contenido.</figcaption></figure>`:''}<a href="${text(r.url)}" target="_blank" rel="noopener">${text(r.title)} ↗</a></div>`;}).join('')}</details>`;
}
function insightEvidence(part){
 const labels={DOCUMENTED:'DOCUMENTADO · arquitectura y función',VISUALLY_RECONSTRUCTED:'RECONSTRUCCIÓN BASADA EN DOCUMENTACIÓN',INFERRED:'REPRESENTACIÓN EDUCATIVA'};
 const paper=part.source?.includes('0574-6'),label=labels[part.evidence]||labels.VISUALLY_RECONSTRUCTED;
 const image=part.media?.startsWith('assets/evidence/insight/')?part.media:null;
 const caption=image?.includes('seis-ac-board')?'Tarjeta SEIS-AC real · figura 58':image?.includes('fig37')?'Péndulo VBB · figura 37':image?.includes('fig20')?'Despiece y dimensiones de la EBox · figura 20':'Arquitectura de SEIS · figura 18';
 const credit='Lognonné y equipo SEIS (2019), Space Science Reviews. Imagen del artículo técnico del instrumento. Conversión a WebP; usada como referencia de reconstrucción.';
 return `<p class="insight-certainty">${label}</p><p class="insight-scope">${part.evidence==='INFERRED'?'La separación de las capas explica su función; no representa un mecanismo histórico.':'La referencia confirma la arquitectura. Las dimensiones finas sin plano público se reconstruyen visualmente; no son CAD de fabricación.'}</p>${part.detailLimit?`<p class="insight-scope">${text(part.detailLimit)}</p>`:''}<details class="insight-evidence"><summary>Ver documentación del componente</summary>${image?`<figure><a href="${image}" target="_blank" rel="noopener" aria-label="Ampliar referencia de ${text(part.name)}"><img src="${image}" alt="${text(caption)}" loading="lazy"></a><figcaption>${caption}. ${credit} <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener">CC BY 4.0</a>.</figcaption></figure>`:''}<a href="${text(part.source)}" target="_blank" rel="noopener">${paper?'Consultar artículo técnico de SEIS':'Consultar referencia NASA/JPL'} ↗</a></details>`;
}
